TEST_CASE("Andes caps (prototype): drain_with_passthrough skips re-reading a "
          "gated CSR the core lacks (ucode/DSP), keeps its passthrough, "
          "re-reads the ALWAYS ones")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x800)] = 0xABCDEULL;  // uitb  (ALWAYS)
  bus.regfile[hybrid::regno_csr(0x801)] = 0x999ULL;    // ucode (DSP off; must NOT be read)

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
  input.priv    = 3;
  input.andes.ucode = 0xDEAD;  // stale passthrough; must survive (not re-read)
  input.andes.uitb  = 0xBEEF;  // stale; must be overwritten by the re-read

  // A core without DSP: ucode (0x801) gate off; every other Andes scalar is
  // ALWAYS in this prototype gate table.
  const hybrid::AndesCaps no_dsp = hybrid::AndesCaps::none();

  hybrid::StateDrain drain(bus, kScratch, no_dsp);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.andes.uitb  == 0xABCDEULL);  // ALWAYS -> re-read from the hart
  CHECK(state.andes.ucode == 0xDEADULL);   // gated off -> passthrough kept
  // ...and no read-COMMAND was issued for the absent CSR (anti-hang, symmetric
  // with the restore gate).
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    CHECK((op.value & 0xFFFFu) != hybrid::regno_csr(0x801));  // ucode
  }
}

