 35 // ax46mpv_advanced config.inc: perf monitor on BUT NDS_SSCOFPMF_SUPPORT=1 --
 36 // the standard Sscofpmf scheme replaces the Andes PMNDS counter CSRs, so the
 37 // PMNDS gates stay off. CoDense + ILM + DLM + PMA on; M-only.
 38 static AndesCaps advanced()
 39 {
 40   AndesCaps c = AndesCaps::none();
 41   c.set(AndesGate::CODENSE);
 42   c.set(AndesGate::ILM);
 43   c.set(AndesGate::DLM);
 44   c.set(AndesGate::PERF_MONITOR);
 45   c.set(AndesGate::PMA);
 46   c.set(AndesGate::ALT_FP);  // BF16 arith + ACE
 47   return c;
 48 }
