  // Andes V5 + M-ext CSR restore: one tolerant abstract write per CSR -- the 13
  // Andes scalars via the HYBRID_ANDES_CSR_LIST X-macro, then PMA (pmaaddr0..15
  // before the even pmacfg, mirroring the PMP restore ordering). Abstract-only
  // by design: a batched Program-Buffer sweep can't tolerate a cmderr on one
  // CSR without corrupting the rest of the batch (a WARL/read-only CSR faults
  // the whole group), whereas the per-CSR abstract path clears the error and
  // moves on. Caps-gated: a CSR the target core lacks (caps_.supports_csr
  // false) is skipped, so an abstract write to an unimplemented CSR can't hang
  // the DM handshake (the ucode/mecc_code cases). minimal: the M-ext block
  // prototypes only menvcfg here; the rest of HYBRID_M_EXT_CSR_LIST plus the
  // baseline/write-mask gating wrap this at their later commits.
  void restore_andes_m_ext(const hybrid_state_v1& state)
  {
    const bool andes = state.flags & HYBRID_FLAG_ANDES;
    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
    if (!andes && !mext) return;

    if (andes) {
#define X(field, addr, name) \
    if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
      HYBRID_ANDES_CSR_LIST(X)
#undef X
      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
    }
    if (mext) {
      // minimal: hand-transport only menvcfg (0x30A), caps-gated. The rest of
      // HYBRID_M_EXT_CSR_LIST joins at the completion commit.
      if (caps_.supports_csr(0x30A))
        write_csr_tolerant(0x30A, state.m_ext.menvcfg);
    }
  }

