          "via abstract commands, never a PB csrr+sd sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize=8

  // Preload the regfile so every re-read CSR has a distinct value.
  uint64_t hv = 0xC5000000ULL;
#define X(field, addr, name) bus.regfile[hybrid::regno_csr(addr)] = hv++;
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  bus.regfile[hybrid::regno_csr(0x30A)] = 0xE0000001ULL;  // menvcfg (M-ext)

